<script setup lang="ts">export type Plan={id:string;name:string;description?:string;price:number;features:string[];featured?:boolean};withDefaults(defineProps<{plans:Plan[];currency?:string;period?:string;modelValue?:string}>(),{currency:'USD',period:'month'});const emit=defineEmits<{'update:modelValue':[id:string]}>();const money=(p:number,c:string)=>new Intl.NumberFormat(undefined,{style:'currency',currency:c}).format(p)</script><template><div class="vx-pricing-grid"><article v-for="plan in plans" :key="plan.id" class="vx-pricing-plan" :class="{'is-featured':plan.featured,'is-selected':modelValue===plan.id}"><span v-if="plan.featured" class="vx-badge">Popular</span><h3>{{plan.name}}</h3><p>{{plan.description}}</p><strong class="vx-pricing-plan__price">{{money(plan.price,currency)}}<small>/{{period}}</small></strong><ul><li v-for="feature in plan.features" :key="feature">✓ {{feature}}</li></ul><button type="button" class="vx-button vx-button--primary" @click="emit('update:modelValue',plan.id)">{{modelValue===plan.id?'Selected':'Choose plan'}}</button></article></div></template>
